this.otherActTemplates = otherActTemplates

local function setTask(config)
  for i, v in ipairs(config) do
    if v.getDataFun then
      v._tasks = v.getDataFun()
    end
  end
end

local function addPurchaseActConfig(config)
  local displayPass = ed.passDataMgr:getDisplayPass()
  local simplePassList = {}
  for id, passInfo in pairs(displayPass or {}) do
    if passInfo.type == "SkinSale" then
      local simplePassActId = SIMPLE_PASS_START_ID + id
      local actCfg = ed.copyTable(otherActTemplates)
      actCfg._type = "other_activity_skin_sale"
      actCfg._head._title = passInfo.extraStr[1]
      actCfg._head._rules = ed.passDefine.SKIN_SALE_RULE
      actCfg._id = simplePassActId
      actCfg._simple_pass_id = id
      actCfg._priority = 299
      
      function actCfg.getRed()
        return ed.passDataMgr:getPassRewardCount(id)
      end
      
      function actCfg._is_show()
        local isEnd = ed.passDataMgr:IsEnded(id)
        local isBuy = ed.passDataMgr:getPassRank(id) >= 1
        local rewardCount = ed.passDataMgr:getPassUnReceiveRewardCount(id)
        if isBuy then
          return 0 < rewardCount
        else
          return not isEnd
        end
        return true
      end
      
      local isExist = false
      for index, actConfig in ipairs(config) do
        if simplePassActId == actConfig._id then
          isExist = true
          break
        end
      end
      if not isExist then
        simplePassList[simplePassActId] = actCfg
      end
    end
  end
  for simplePassActId, cfg in pairs(simplePassList) do
    table.insert(config, cfg)
  end
end

this.addPurchaseActConfig = addPurchaseActConfig

function ed.othActConfig()
  local object = {}
  setmetatable(object, {__index = this})
  addPurchaseActConfig(object.config)
  setTask(object.config)
  return object
end
